import sys

def find_longest_valid_substring(S):
    n = len(S)
    max_length = -1

    # Check all possible substrings
    for start in range(n):
        for end in range(start + 1, n + 1):
            P = S[start:end]
            is_valid = True

            # Check if no non-empty substring of P is a prefix of S
            for i in range(1, len(P)):
                if P[:i] == S[:i]:
                    is_valid = False
                    break

            # Check if no non-empty substring of P is a suffix of S
            for i in range(1, len(P)):
                if P[-i:] == S[-i:]:
                    is_valid = False
                    break

            if is_valid:
                max_length = max(max_length, len(P))

    return max_length

